import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU testing","description":"","frontmatter":{},"headers":[],"relativePath":"dev/qemu-testing.md","filePath":"dev/qemu-testing.md"}'),i={name:"dev/qemu-testing.md"};function r(d,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="qemu-testing" tabindex="-1">QEMU testing <a class="header-anchor" href="#qemu-testing" aria-label="Permalink to &quot;QEMU testing&quot;">​</a></h1><p>How the project actually tests in QEMU - the same recipes the release gates use, plus the QEMU-specific behaviors (errata, firmware paths, input injection) that cost hours if you learn them the hard way. Evidence-extraction methodology is in <a href="./debug-handbook.html">debug-handbook.md</a>; the suite mechanics are in <a href="./e2e-suites.html">e2e-suites.md</a>.</p><h2 id="_1-interactive-boot" tabindex="-1">1. Interactive boot <a class="header-anchor" href="#_1-interactive-boot" aria-label="Permalink to &quot;1. Interactive boot&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios          # default: 512M, e1000 + user net, serial on stdio</span></span>
<span class="line"><span>make run-uefi          # OVMF via a pflash copy of OVMF_FD</span></span>
<span class="line"><span>make run-bios-gui      # GTK window (PS/2 keyboard receives scancodes)</span></span>
<span class="line"><span>make run-uefi-gui</span></span>
<span class="line"><span>make run-bios-persist  # -snapshot OFF: /etc edits persist in build/etc.img</span></span>
<span class="line"><span>make shot-bios         # VNC + monitor screendump -&gt; PNG (tools/qemu_shot_vnc.py)</span></span></code></pre></div><p>The <code>run-*</code> targets build the ISO and a fresh 32 MiB FAT32 <code>/etc</code> volume (<code>build/etc.img</code>) so persistence tests start clean; the persist variants deliberately keep your edits.</p><h2 id="_2-ovmf-paths" tabindex="-1">2. OVMF paths <a class="header-anchor" href="#_2-ovmf-paths" aria-label="Permalink to &quot;2. OVMF paths&quot;">​</a></h2><ul><li>Default: <code>OVMF_FD = $(OC_TOOLS)/share/ovmf/OVMF.fd</code> - derived from the toolchain root (<code>/usr</code> on a system install, <code>&lt;tree&gt;/share/ovmf/OVMF.fd</code> in the no-root sandbox from <code>tools/install-toolchain.sh</code>).</li><li>The <code>run-uefi</code> targets copy <code>OVMF.fd</code> to a pflash <em>work</em> file (<code>-drive if=pflash,...OVMF_WORK.fd</code>) so the firmware vars image is writable but your pristine <code>OVMF.fd</code> is never modified.</li><li>The release boot gates run OVMF through pflash CODE+VARS on a FRESH mktemp log per run (BUG #63 fake-green fix - appending to an old log made a dead boot look green).</li><li><code>QEMU_DATADIR</code>/<code>SEABIOS_DIR</code> follow <code>OC_TOOLS</code> the same way and feed QEMU <code>-L</code> and the BIOS lookup.</li></ul><h2 id="_3-deterministic-boot-log-testing" tabindex="-1">3. Deterministic boot-log testing <a class="header-anchor" href="#_3-deterministic-boot-log-testing" aria-label="Permalink to &quot;3. Deterministic boot-log testing&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso</span></span></code></pre></div><p>pexpect over <code>-serial mon:stdio</code> (latin-1, NUL-stripped, ANSI-stripped, prompt <code>(?:ush&gt;|oc&gt;)\\s</code>), then the fixed command battery with per-command-section assertions. Boot to the <code>ush&gt;</code> prompt takes ~2 s of wall time; the full 31-check battery runs in well under a minute. The full check list: <a href="./e2e-suites.html">e2e-suites.md</a> section 2.</p><h2 id="_4-qemu-specific-behaviors-and-errata" tabindex="-1">4. QEMU-specific behaviors and errata <a class="header-anchor" href="#_4-qemu-specific-behaviors-and-errata" aria-label="Permalink to &quot;4. QEMU-specific behaviors and errata&quot;">​</a></h2><p>The behaviors that differ from real hardware (all verified in source or with in-kernel traces):</p><ul><li><strong>AHCI/NVMe bounce buffers are a QEMU-visible contract</strong>: AHCI does READ/WRITE DMA EXT through a per-port 4 KiB page-aligned bounce buffer split into chunks of at most 8 sectors (one PRDT entry per chunk); NVMe uses one page bounce buffer with 64-bit PRPs. If you touch the storage drivers, keep the bounce discipline - QEMU&#39;s DMA engine is strict about PRDT alignment in ways some real controllers are not.</li><li><strong>PIIX3 prog-if quirk</strong>: the ATA BMDMA probe matches IDE class 0x0101 with ANY prog-if (mask 0xFFFF00) because QEMU&#39;s PIIX3 reports 0x80 while real chips report 0x00/0x8A/... - a base-class-only probe latches onto IDE controllers wrongly.</li><li><strong>TCO presence</strong>: the Intel TCO watchdog lives on the LPC bridge of the <strong>q35</strong> machine (ICH9-LPC, PCI 00:1f.0); the default <code>pc</code> machine (PIIX3) has none - the probe honestly reports &quot;none&quot;. Watchdog E2E scenarios boot q35 with <code>-no-reboot</code>.</li><li><strong>HDA + 44100 freezes the VM</strong>: the driver programs it correctly on real hardware, but under QEMU the whole VM freezes - so <code>sample_rate_test</code> reports the caps bit only for that combination. This is reported honestly, not papered over.</li><li><strong>Serial RX bytes drop after an HMP screendump</strong>: QEMU intermittently loses serial input right after a monitor screendump (verified with an in-kernel RX trace). Functional test rounds therefore never take screenshots; flapping checks re-run isolated (<code>wp10_native_manual.py</code>).</li><li><strong>xHCI DMA above 4 GiB is refused</strong> at probe and per-transfer - check your <code>-m</code> size if an xHCI device &quot;vanishes&quot;.</li><li><strong>Virtio-blk legacy capacity</strong> is read at config offset 0x14 (the fix for the old &quot;capacity = 0&quot; bug).</li><li><strong>e1000 resume</strong>: <code>net_e1000_resume()</code> replays legacy e1000 register programming after ACPI S3 (QEMU resets the NIC on suspend).</li><li><strong>Display</strong>: the MB2 header requests 800x600x32; UEFI-GOP hands off RGBX while BIOS-VBE hands off BGRX - <code>screen_fb_rgb</code> derives masks from the GRUB tag, so both work.</li><li><strong>Warm resets</strong> keep DRAM: the boot-state islands 0x98000/ 0x9B000 survive QEMU warm resets (E820-reserved, empirically proven); cold boots clear them and every reader validates the magic first.</li></ul><h2 id="_5-driving-the-ocbl-boot-menu-sendkey" tabindex="-1">5. Driving the OCBL boot menu (sendkey) <a class="header-anchor" href="#_5-driving-the-ocbl-boot-menu-sendkey" aria-label="Permalink to &quot;5. Driving the OCBL boot menu (sendkey)&quot;">​</a></h2><p>The OCBL boot menu (the in-tree bootloader, 10 s countdown) reads PS/2 keys - it exists before the kernel and before any serial console. In headless QEMU you drive it through the HMP monitor:</p><ul><li>Start QEMU with <code>-monitor stdio</code> (or the unix-socket monitor the test rigs use) alongside <code>-serial stdio</code>.</li><li><code>sendkey down</code> / <code>sendkey up</code> move the highlight; <code>sendkey ret</code> boots the entry; the countdown boots the default after 10 s.</li><li>Picking the OCIRE entry in the menu writes a USER_REQUEST record (the exact distinction OCIRE reports: &quot;requested by the user&quot; vs a judged failure with repair advice) - the interactive sendkey sessions in the WP04/WP07a evidence transcripts drive exactly this.</li><li>The same <code>sendkey</code> channel is how the suites deliver keystrokes a serial link cannot carry (arrows, Home/End) into the <em>guest</em> (line-editor and editor tests); pointer input goes through QMP <code>input-send-event</code> (HMP mouse_move is dead on <code>-display none</code> + QEMU 10).</li></ul><h2 id="_6-screenshots" tabindex="-1">6. Screenshots <a class="header-anchor" href="#_6-screenshots" aria-label="Permalink to &quot;6. Screenshots&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make shot-bios     # boot screenshot to build/shot-bios.png (VNC + PIL)</span></span>
<span class="line"><span>make shot-uefi</span></span></code></pre></div><p>The framebuffer assertion (regression check 1) requires the PPM screendump to show &gt;= 2 colors and a measurable foreground ratio - a serial-only gate once passed on a dead panel, so screenshots are the <em>only</em> accepted proof of a live display, and functional rounds avoid them because of the serial-RX errata above.</p><h2 id="_7-qemu-devices-that-map-to-drivers" tabindex="-1">7. QEMU devices that map to drivers <a class="header-anchor" href="#_7-qemu-devices-that-map-to-drivers" aria-label="Permalink to &quot;7. QEMU devices that map to drivers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>QEMU flag</th><th>Kernel driver</th></tr></thead><tbody><tr><td><code>-device e1000</code> (default net)</td><td>e1000 NIC (built-in path)</td></tr><tr><td><code>-device e1000e</code> etc.</td><td>WP-10b framework families</td></tr><tr><td><code>-device virtio-blk-pci</code></td><td>virtio-blk (<code>vda</code>)</td></tr><tr><td><code>-device nvme</code></td><td>NVMe (<code>nvme0</code>)</td></tr><tr><td><code>-device ahci</code> + SATA disk</td><td>AHCI (<code>sda</code>...)</td></tr><tr><td>IDE disks</td><td>ATA PIO + Bus-Master DMA (<code>hda</code>..)</td></tr><tr><td><code>-device usb-storage</code> through xHCI</td><td>USB MSC (registers block devices)</td></tr><tr><td><code>-device AC97</code> / <code>-device intel-hda</code> + <code>-device hda-output</code></td><td>sound</td></tr><tr><td><code>-device virtio-sound-pci</code></td><td>virtio-snd</td></tr><tr><td>q35 machine</td><td>Intel TCO watchdog</td></tr><tr><td><code>-bios OVMF.fd</code> / pflash</td><td>UEFI boot path</td></tr><tr><td>LSI 53C895A (<code>-device lsi</code>)</td><td>SCSI (camera-family <code>scsi</code> op)</td></tr><tr><td><code>-acpitable file=wdat.bin</code></td><td>ACPI WDAT watchdog (tools/make_wdat_table.py)</td></tr></tbody></table><h2 id="_8-speed" tabindex="-1">8. Speed <a class="header-anchor" href="#_8-speed" aria-label="Permalink to &quot;8. Speed&quot;">​</a></h2><ul><li><code>-display none -serial mon:stdio</code> for every automated run.</li><li>Boot to the <code>ush&gt;</code> prompt takes ~2 s of wall time in the regression environment.</li><li>The compile cache (<code>tools/oc_cc.sh</code>) keeps the <em>build</em> inner loop warm; see <a href="./build.html">build.md</a> section 7.</li><li><code>-icount</code> gives timing stability for network tests; the reproducible build means a crash reproduced twice is the same bytes both times.</li></ul>`,23)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
